/**
 * 背景音乐内联数据（与 assets/audio/bgm.mp3 同一份音频，base64 内联）。
 *
 * 为什么不用 /assets/audio/bgm.mp3 直接播：内置 H5 预览器把包内绝对路径解析到
 * 站点根，`/assets/...` 取不到（配图当初也是同样问题，才改成内联 data URI）。
 * 预览器一旦取不到，旧实现会退化成 Web Audio 合成的「嘀嘀」音，听起来就是音效，
 * 完全不像背景音乐——所以这里把真实钢琴曲内联进来，预览与真机听到的是同一段。
 *
 * 曲目：Bach《哥德堡变奏曲》咏叹调（Public Domain Mark 1.0，无需署名），
 * 截取 00:20–00:42 共 22 秒，首尾淡入淡出，响度归一到 -20 LUFS，48kbps 单声道。
 * 由 illustration-samples/build_bgm_mp3.py 生成，请勿手改。
 */
const BGM_MP3_BASE64 = '';

module.exports = {
  dataUri: 'data:audio/mpeg;base64,' + BGM_MP3_BASE64,
  title: "Bach — Goldberg Variations, Aria",
  composer: "Johann Sebastian Bach (1685–1750)",
  license: "Public Domain Mark 1.0",
  credit: "",
  duration: 22,
};
